def verifier(assign):
    # Validate and solve for m; ensure uniqueness and enforce the consecutive-integer constraints rigorously.
    required = ['r','s','p','q','u','v','D','E']
    for k in required:
        if k not in assign:
            # Missing parameter
            return (False, None)
    r = assign['r']; s = assign['s']; p = assign['p']; q = assign['q']; u = assign['u']; v = assign['v']; D = assign['D']; E = assign['E']
    # Helper to check validity and compute extremes
    def compute_extremes(m):
        if not isinstance(m, int) or m <= 0:
            return None
        SA = r*m + s
        LA = m
        two_avgA_num = 2*SA
        if two_avgA_num % LA != 0:
            return None
        kA = two_avgA_num // LA
        if (LA % 2 == 1 and (kA % 2) != 0) or (LA % 2 == 0 and (kA % 2) != 1):
            return None
        two_gA = kA + (LA - 1)
        two_lA = kA - (LA - 1)
        if two_gA % 2 != 0 or two_lA % 2 != 0:
            return None
        gA = two_gA // 2
        lA = two_lA // 2
        LB = p*m + q
        if LB <= 0:
            return None
        SB = u*m + v
        two_avgB_num = 2*SB
        if two_avgB_num % LB != 0:
            return None
        kB = two_avgB_num // LB
        if (LB % 2 == 1 and (kB % 2) != 0) or (LB % 2 == 0 and (kB % 2) != 1):
            return None
        two_gB = kB + (LB - 1)
        two_lB = kB - (LB - 1)
        if two_gB % 2 != 0 or two_lB % 2 != 0:
            return None
        gB = two_gB // 2
        lB = two_lB // 2
        return gA, lA, gB, lB
    solutions = []
    # Heuristic bound: only m dividing 2*s can possibly make A valid. Enumerate divisors of 2*s to reduce search.
    from math import gcd
    S2 = 2*s
    cand_ms = set()
    # Include some reasonable bounds to avoid pathological cases
    # Collect positive divisors of |2*s| as candidates, plus a fallback range.
    absS2 = abs(S2)
    if absS2 == 0:
        # If s == 0, then 2*s == 0; any m could divide 0. Fall back to a range.
        cand_ms.update(range(1, 50000))
    else:
        # enumerate divisors up to a limit
        import math
        for d in range(1, min(50000, absS2) + 1):
            if absS2 % d == 0:
                cand_ms.add(d)
        # Also include a small fallback range
        cand_ms.update(range(1, 10000))
    count = 0
    ans_m = None
    for m in sorted(cand_ms):
        ext = compute_extremes(m)
        if ext is None:
            continue
        gA, lA, gB, lB = ext
        if abs(gA - gB) == D and abs(lA - lB) == E:
            count += 1
            ans_m = m
            if count > 1:
                # Not unique; reject
                return (False, None)
    if count == 1:
        return (True, ans_m)
    return (False, None)
